def solve(s):
    n = len(s)
    f = [[0] * n for _ in range(n)]
    for i in range(n): f[i][i] = 1
    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            f[l][r] = f[l+1][r] + 1
            for k in range(l + 1, r + 1):
                if s[k] == s[l]:
                    mid = f[l+1][k-1] if k - 1 >= l + 1 else 0
                    f[l][r] = min(f[l][r], mid + f[k][r])
    return f[0][n-1]
